class BrowserHistory(homepage:String){private val history=mutableListOf(homepage);private var current=0;fun visit(url:String){while(history.size>current+1)history.removeAt(history.lastIndex);history.add(url);current++};fun back(steps:Int):String{current=maxOf(0,current-steps);return history[current]};fun forward(steps:Int):String{current=minOf(history.lastIndex,current+steps);return history[current]}}
